  const i128 norm = short_norm ? i128{v[0] * v[0] + v[1] * v[1] + v[2] * v[2]}
                               : i128{v[0]} * v[0] + i128{v[1]} * v[1] + i128{v[2]} * v[2];
  i128 total = denominator_ * norm;
  for (int j = 0; j < 3; ++j) total += numerator_[j] * (-2 * i128{v[j]});
  sign = (total > 0) - (total < 0);
  return {};
}

